// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // The test contract is c.owner (msg.sender during setUp); accept ETH so the
    // owner's `transfer` in withdrawAll succeeds on the reference.
    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);

        // Fund the test contract, deposit `amount` into c via its payable fallback.
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        require(address(c).balance == amount, "deposit not reflected");

        // Owner (this contract) withdraws everything.
        c.withdrawAll();

        // Rule: after withdrawAll, the contract retains no funds.
        assertTrue(address(c).balance == 0);
    }
}
